import { useState } from 'react';
import { ChevronRight, Wrench, Camera, Sparkles } from 'lucide-react';
import { IndustrialHeader } from './IndustrialHeader';

interface Props {
  onComplete: () => void;
  elapsedTime: number;
  productName: string;
  operatorSettings: {
    operatorName: string;
    line: string;
    station: string;
  };
  onBack: () => void;
  onSettings?: () => void;
  // NIEUW: rapporteert elke doorlopen montagestap terug naar de operator-
  // app, voor de SMED-registratie. De starttijd wordt NIET hier bepaald
  // — die komt van de centrale klok in main.tsx, zodat er geen gaten
  // ontstaan tussen deze stap en wat ervoor kwam.
  onStepLog?: (step: string, stopTime: number) => void;
}

interface ProductionStep {
  id: number;
  title: string;
  instruction: string;
  imageUrl: string | null;
  requiresTool: boolean;
  toolName?: string;
  mirror?: boolean;
  isFinalPhoto?: boolean;
}

