export function ProductionStepsScreen({ onComplete, elapsedTime, productName, operatorSettings, onBack, onSettings, onStepLog }: Props) {
  const steps =
    productName === 'Product 1'
      ? PRODUCT1_STEPS
      : PRODUCT2_STEPS;

  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const currentStep = steps[currentStepIndex];
  const totalSteps = steps.length;

  const logCurrentStep = () => {
    onStepLog?.(currentStep.title, Date.now());
  };

  const handleNext = () => {
    logCurrentStep();

    if (currentStepIndex < totalSteps - 1) {
      setCurrentStepIndex(currentStepIndex + 1);
    } else {
      onComplete();
    }
  };

  const handlePrevious = () => {
    if (currentStepIndex > 0) {
      setCurrentStepIndex(currentStepIndex - 1);
    } else {
      onBack();
    }
  };

  return (
    <div className="h-full min-h-0 flex flex-col bg-gray-100 overflow-hidden">
      <IndustrialHeader 
        title={
          currentStep.isFinalPhoto
            ? 'Montage voltooid'
            : `Montage, stap ${currentStepIndex + 1} van ${totalSteps - 1}`
        }
        subtitle={`${productName} assemblage`}
        showTimer
        timerLabel="Montagetijd"
        elapsedTime={elapsedTime}
        operatorSettings={operatorSettings}
        onBack={handlePrevious}
        onSettings={onSettings}
      />
      
      <div className="flex-1 min-h-0 overflow-y-auto flex flex-col md:flex-row p-8 gap-8 max-w-[1280px] mx-auto w-full">
        <div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 p-6 flex flex-col">
          <div className="flex-1 flex items-center justify-center bg-gray-50 rounded-lg overflow-hidden">
            {currentStep.imageUrl ? (
              <img
                src={currentStep.imageUrl}
                alt={currentStep.title}
                className="max-w-full max-h-full object-contain rounded-lg"
                style={currentStep.mirror ? { transform: 'scaleX(-1)' } : undefined}
              />
            ) : (
              <div className="flex flex-col items-center justify-center text-center p-8">
                <Sparkles className="w-16 h-16 text-gray-300 mb-4" />
                <p className="text-sm text-gray-400 font-medium">Geen referentiefoto voor deze stap</p>
              </div>
            )}
          </div>
          
          {!currentStep.isFinalPhoto && (
            <div className="mt-4 bg-gray-200 rounded-full h-2">
              <div 
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${((currentStepIndex + 1) / (totalSteps - 1)) * 100}%` }}
              />
            </div>
          )}
        </div>

        <div className="w-full md:w-96 flex flex-col gap-5">
          
          {currentStep.isFinalPhoto && (
            <div className="bg-emerald-50 border-l-4 border-emerald-600 rounded-lg p-5 flex items-center gap-3">
              <Camera className="w-6 h-6 text-emerald-600 flex-shrink-0" />
              <p className="text-sm text-emerald-800 font-medium">
                Volgende stap: eindcontrole met de telefoon-camera.
              </p>
            </div>
          )}

          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h3 className="text-2xl text-gray-800 font-bold mb-4 uppercase">
              {currentStep.title}
            </h3>
            <p className="text-sm text-gray-700 leading-relaxed">
              {currentStep.instruction}
            </p>
          </div>

          {currentStep.requiresTool && (
            <div className="bg-blue-50 border-l-4 border-blue-600 rounded-lg p-5">
              <div className="flex items-center gap-3">
                <Wrench className="w-6 h-6 text-blue-600" />
                <div>
                  <h4 className="text-sm text-blue-800 font-bold uppercase">Gereedschap</h4>
                  <p className="text-sm text-blue-700">{currentStep.toolName}</p>
                </div>
              </div>
            </div>
          )}

          <div className="flex-1"></div>

          <button
            onClick={handleNext}
            className="w-full bg-blue-500 hover:bg-blue-600 text-white text-lg py-4 px-6 rounded-lg transition-colors flex items-center justify-center gap-3 font-medium shadow-sm"
          >
            {currentStep.isFinalPhoto ? 'Naar eindcontrole' : 'Volgende'}
            <ChevronRight className="w-6 h-6" />
          </button>
        </div>
      </div>
    </div>
  );
}
